changeSet.sql:
with request_types(code) AS ( SELECT unnest(ARRAY['INSTALLATION_ACCOUNT_OPENING', 'SYSTEM_MESSAGE_NOTIFICATION', 'PERMIT_ISSUANCE', 'PERMIT_SURRENDER', 'PERMIT_REVOCATION', 'PERMIT_TRANSFER_A', 'PERMIT_TRANSFER_B', 'PERMIT_VARIATION', 'PERMIT_NOTIFICATION', 'PERMIT_REISSUE', 'NON_COMPLIANCE', 'NER', 'DOAL', 'AER', 'VIR', 'AIR', 'DRE', 'WITHHOLDING_OF_ALLOWANCES', 'RETURN_OF_ALLOWANCES', 'INSTALLATION_ONSITE_INSPECTION', 'INSTALLATION_AUDIT', 'HSE_TI', 'BDR', 'BDRS2', 'PERMANENT_CESSATION', 'ALR', 'WASTE_QDR', 'AVIATION_ACCOUNT_CLOSURE', 'AVIATION_NON_COMPLIANCE', 'EMP_REISSUE', 'AVIATION_VIR', 'EMP_ISSUANCE_UKETS', 'EMP_VARIATION_UKETS', 'AVIATION_AER_UKETS', 'AVIATION_DRE_UKETS', 'EMP_ISSUANCE_CORSIA', 'EMP_VARIATION_CORSIA', 'AVIATION_AER_CORSIA', 'AVIATION_DOE_CORSIA', 'AVIATION_AER_CORSIA_ANNUAL_OFFSETTING', 'AVIATION_AER_CORSIA_3YEAR_PERIOD_OFFSETTING']) ), rules(handler, role_type) as ( select * from ( values ('requestAccessHandler', 'REGULATOR'), ('requestAccessHandler', 'OPERATOR'), ('requestAccountBasedAccessHandler', 'VERIFIER') ) as r(handler, role_type) ) insert into au_rule(id, resource_type, resource_sub_type, handler, role_type, scope) select nextval('au_rule_seq'), 'REQUEST', rt.code, r.handler, r.role_type, null from request_types rt cross join rules r;
with request_types(code) AS ( SELECT unnest(ARRAY['PERMIT_BATCH_REISSUE', 'EMP_BATCH_REISSUE']) ), rules(handler, role_type) as ( select * from ( values ('requestAccessHandler', 'REGULATOR') ) as r(handler, role_type) ) insert into au_rule(id, resource_type, resource_sub_type, handler, role_type, scope) select nextval('au_rule_seq'), 'REQUEST', rt.code, r.handler, r.role_type, null from request_types rt cross join rules r;
INSERT INTO au_service_rule (rule_id, service_id) SELECT r.id, s.id FROM ( select id from au_rule where resource_type = 'REQUEST' and resource_sub_type is not null and role_type = 'REGULATOR' and scope is null ) r CROSS JOIN ( select s.id from au_rule r join au_service_rule sr on sr.rule_id = r.id join au_service s on s.id = sr.service_id where r.resource_type = 'REQUEST' and r.resource_sub_type is null and r.role_type = 'REGULATOR' and r.scope is null ) s;
INSERT INTO au_service_rule (rule_id, service_id) SELECT r.id, s.id FROM ( select id from au_rule where resource_type = 'REQUEST' and resource_sub_type is not null and role_type = 'OPERATOR' and scope is null ) r CROSS JOIN ( select s.id from au_rule r join au_service_rule sr on sr.rule_id = r.id join au_service s on s.id = sr.service_id where r.resource_type = 'REQUEST' and r.resource_sub_type is null and r.role_type = 'OPERATOR' and r.scope is null ) s;
INSERT INTO au_service_rule (rule_id, service_id) SELECT r.id, s.id FROM ( select id from au_rule where resource_type = 'REQUEST' and resource_sub_type is not null and role_type = 'VERIFIER' and scope is null ) r CROSS JOIN ( select s.id from au_rule r join au_service_rule sr on sr.rule_id = r.id join au_service s on s.id = sr.service_id where r.resource_type = 'REQUEST' and r.resource_sub_type is null and r.role_type = 'VERIFIER' and r.scope is null ) s;
--delete deprecated rules delete from au_service_rule where rule_id in ( select id from au_rule where resource_type = 'REQUEST' and resource_sub_type is null and scope is null);
delete from au_rule where resource_type = 'REQUEST' and resource_sub_type is null and scope is null;

